# Coroutines v2 · Phần 4 · PR Coroutines trong thực tế (Deep Dive: "Common use cases", "Recipes", "Using coroutines from other languages" (chỉ phần Java),
# "Launching coroutines vs. suspending functions", "Best practices"; trang PDF 377–449) + sim coroutines.launchsusp.

def add(a):
    def B(ch, sec, n, field, vi, en=None):
        a('%s.sec.%s.b.%02d.%s' % (ch, sec, n, field), vi, vi if en is None else en)

    # ---------------- sim coroutines.launchsusp ----------------
    m = lambda k, vi, en=None: a('m.launchsusp.' + k, vi, en)
    m('title', 'Hàm thường launch trên scope, hay hàm suspend?', 'A regular function launching on a scope, or a suspending function?')
    m('overview', 'Người gọi (một coroutine trong viewModelScope) gọi `sendNotifications(n1, n2, n3)`; mỗi lần gửi mất 1000, 2000, 1500 ms. Chọn kiểu hàm và một sự cố rồi bấm Step: người gọi đi tiếp lúc nào, lỗi đi đâu, hủy lan tới đâu?', 'The caller (a coroutine in viewModelScope) calls `sendNotifications(n1, n2, n3)`; sending takes 1000, 2000, 1500 ms. Pick the kind of function and an incident, then press Step: when does the caller continue, where does the error go, how far does cancellation reach?')
    m('wrapup', 'Hàm thường + scope ngoài: trả về ngay, không chờ, lỗi do scope xử lý, và việc gửi KHÔNG bị hủy cùng người gọi (nó thuộc scope kia). Hàm suspend + supervisorScope: người gọi chờ tới khi mọi con xong, lỗi của một con không kéo các con khác, và hủy người gọi thì hủy luôn các lần gửi đang chạy. Có lựa chọn thì ưu tiên hàm suspend vì dễ điều khiển và đồng bộ hơn.', 'Regular function + outer scope: returns at once, does not wait, errors are handled by that scope, and sending is NOT cancelled with the caller (it belongs to the other scope). Suspending function + supervisorScope: the caller waits until every child is done, one child\'s error does not take the others down, and cancelling the caller cancels the sends still running. Given the choice, prefer the suspending function: it is easier to control and synchronize.')
    m('simp.1', 'Thời lượng gửi, thời điểm lỗi (800 ms) và thời điểm hủy (1200 ms) là giả định của site. Hành vi theo cách Marcin Moskała so sánh launch với hàm suspend, và theo tài liệu `supervisorScope`.', 'Send durations, the failure time (800 ms) and the cancellation time (1200 ms) are the site\'s assumptions. Behaviour follows Marcin Moskała\'s comparison of launching coroutines with suspending functions, and the `supervisorScope` docs.')
    m('ctl.hint', 'So "người gọi" ở hai kiểu hàm, rồi thử hai sự cố.', 'Compare the "caller" row for both kinds of function, then try both incidents.')
    m('ctl.mode', 'Kiểu hàm', 'Kind of function')
    m('ctl.mode.scope', 'fun + notificationScope.launch', 'fun + notificationScope.launch')
    m('ctl.mode.susp', 'suspend fun + supervisorScope', 'suspend fun + supervisorScope')
    m('scope.scope', 'fun + scope', 'fun + scope')
    m('scope.susp', 'suspend fun', 'suspend fun')
    m('ctl.ev', 'Sự cố', 'Incident')
    m('ctl.ev.none', 'không có', 'none')
    m('ctl.ev.fail', 'gửi n2 lỗi ở 800 ms', 'sending n2 fails at 800 ms')
    m('ctl.ev.cancel', 'người gọi bị hủy ở 1200 ms', 'the caller is cancelled at 1200 ms')
    m('diagramTitle', 'Người gọi và ba lần gửi theo thời gian', 'The caller and three sends over time')
    m('diagramDesc', 'Hàng người gọi và ba hàng gửi thông báo', 'A caller row and three notification rows')
    m('n.c', 'Người gọi', 'Caller')
    m('n.n1', 'gửi n1', 'send n1')
    m('n.n2', 'gửi n2', 'send n2')
    m('n.n3', 'gửi n3', 'send n3')
    m('col', 'Kiểu hàm', 'Kind')
    m('axis', 'ms (thời gian của mã) →', 'ms (code time) →')
    m('met.done', 'Gửi xong', 'Sent')
    m('met.lost', 'Lỗi hoặc bị hủy', 'Failed or cancelled')
    m('bar.run', 'đang chạy', 'running')
    m('bar.wait', 'người gọi đang chờ (suspend)', 'caller waiting (suspended)')
    m('lbl.waitKids', 'chờ các con', 'waiting for children')
    S = [
        ('callScope', 'Gọi hàm thường: trả về ngay', 'Calling the regular function: it returns at once', 'Hàm chỉ `launch` ba coroutine trên `notificationScope` rồi trả về trong vài micro giây. Người gọi in "Tiếp tục" ngay, không biết việc gửi xong hay chưa.', 'The function just `launch`es three coroutines on `notificationScope` and returns within microseconds. The caller prints "Continue" right away, without knowing whether sending has finished.'),
        ('callSusp', 'Gọi hàm suspend: người gọi chờ', 'Calling the suspending function: the caller waits', '`supervisorScope` tạo ba con là con của chính người gọi (qua scope), và chỉ trả về khi mọi con xong. Người gọi bị suspend.', '`supervisorScope` creates three children that belong to the caller (through the scope) and returns only when every child is done. The caller is suspended.'),
        ('done', 'Gửi n{n} xong', 'n{n} sent', 'Một lần gửi hoàn tất.', 'One send has completed.'),
        ('failScope', 'Gửi n{n} lỗi: scope xử lý', 'Sending n{n} fails: the scope handles it', 'Lỗi đi lên `notificationScope` (có SupervisorJob): các lần gửi khác chạy tiếp; lỗi tới `handler` của scope (ghi log). Nếu scope KHÔNG có handler, trên JVM lỗi tới `Thread.uncaughtExceptionHandler` của luồng (chương trình thường chỉ in stack trace), còn trên Android điều đó làm CRASH app. Người gọi không bao giờ biết.', 'The error goes up to `notificationScope` (with a SupervisorJob): the other sends continue; the error reaches the scope\'s `handler` (logged). If the scope has NO handler, on the JVM the error goes to the thread\'s `Thread.uncaughtExceptionHandler` (a program usually just prints the stack trace), while on Android that CRASHES the app. The caller never finds out.'),
        ('failSusp', 'Gửi n{n} lỗi: supervisorScope bỏ qua', 'Sending n{n} fails: supervisorScope ignores it', '`supervisorScope` không để lỗi của một con hủy các con khác hay chính nó; mỗi con tự xử lý lỗi bằng handler trong context của nó (`launch(handler)`). Thiếu handler thì lỗi đi theo đường “không ai bắt”: trên Android, app crash. Hàm vẫn chờ n1, n3 rồi trả về bình thường.', '`supervisorScope` does not let one child\'s failure cancel the others or itself; each child handles its error with the handler in its context (`launch(handler)`). Without a handler the error takes the "uncaught" path: on Android, the app crashes. The function still waits for n1, n3 and then returns normally.'),
        ('cancelScope', 'Người gọi bị hủy, việc gửi vẫn chạy', 'The caller is cancelled, sending continues', 'Các coroutine gửi là con của `notificationScope`, không phải của người gọi. Hủy người gọi không chạm tới chúng; chỉ hủy `notificationScope` mới dừng được.', 'The sending coroutines are children of `notificationScope`, not of the caller. Cancelling the caller does not touch them; only cancelling `notificationScope` stops them.'),
        ('cancelSusp', 'Người gọi bị hủy: hủy luôn các lần gửi đang chạy', 'The caller is cancelled: the running sends are cancelled too', 'Structured concurrency: hủy cha thì hủy mọi con. n2 và n3 bị hủy giữa chừng.', 'Structured concurrency: cancelling the parent cancels every child. n2 and n3 are cancelled midway.'),
        ('resume', 'Mọi con xong: người gọi đi tiếp', 'Every child is done: the caller continues', '`supervisorScope` trả về; người gọi in "Tiếp tục" và biết chắc việc gửi đã kết thúc.', '`supervisorScope` returns; the caller prints "Continue" and knows for sure that sending has finished.'),
        ('end', 'Kết thúc', 'The end', 'So lúc người gọi đi tiếp, và số lần gửi xong, lỗi hay bị hủy.', 'Compare when the caller continued, and how many sends completed, failed or were cancelled.'),
    ]
    for sid, tv, te, xv, xe in S:
        m('s.%s.title' % sid, tv, te); m('s.%s.explain' % sid, xv, xe); m('ev.' + sid, tv, te)
    for k, vi, en in [
        ('scopeReturns', 'Không chờ, lỗi do scope xử lý (cần handler), ngữ cảnh và quan hệ cha con lấy từ scope.', 'No waiting, errors handled by the scope (it needs a handler), context and parent link taken from the scope.'),
        ('suspWaits', 'Chờ các con, tự xử lý (ném hoặc nuốt) lỗi, ngữ cảnh lấy từ người gọi.', 'Waits for its children, handles (throws or swallows) errors itself, context taken from the caller.'),
        ('failScope', 'Người gọi không có cách nào biết lần gửi này đã thất bại. Và nếu quên handler trong scope, trên Android lỗi này làm crash app ([[src:kx-ceh]], [[src:and-crash]]).', 'The caller has no way of knowing this send failed. And if you forget the handler in the scope, on Android this error crashes the app ([[src:kx-ceh]], [[src:and-crash]]).'),
        ('failSusp', 'Với `coroutineScope` thay vì `supervisorScope`, lỗi này sẽ hủy các con khác và hàm ném lỗi cho người gọi.', 'With `coroutineScope` instead of `supervisorScope`, this error would cancel the other children and the function would throw to the caller.'),
        ('cancelScope', 'Đây có thể là điều bạn muốn (gửi nốt dù người dùng rời màn hình), hoặc là rò rỉ công việc: hãy chọn có chủ đích.', 'This may be what you want (finish sending even if the user leaves the screen), or a work leak: choose deliberately.'),
        ('cancelSusp', 'Hủy lan xuống con: không còn việc chạy vô ích sau khi người gọi không cần nữa.', 'Cancellation reaches the children: no useless work keeps running once the caller no longer needs it.')]:
        m('co.' + k, vi, en)
    a('cap.launchsusp', 'Hàng người gọi: thanh liền là đang chạy, thanh viền đứt là đang chờ các con. Ba hàng gửi: ✓ xong, ✕ lỗi, ⊘ bị hủy; → là lúc người gọi đi tiếp.', 'Caller row: a solid bar is running, a dashed bar is waiting for the children. Three send rows: ✓ done, ✕ failed, ⊘ cancelled; → marks when the caller continues.')

    # ---------------- chương PR ----------------
    C = 'pr'
    a(C + '.title', 'Coroutines trong thực tế: theo tầng, công thức, Java và best practices', 'Coroutines in practice: by layer, recipes, Java and best practices')
    a(C + '.essence',
      'Ứng dụng thường có ba tầng. Tầng dữ liệu nói chuyện với thư viện: dùng hàm suspend của Retrofit/Room; bọc callback bằng `suspendCancellableCoroutine`; bọc lời gọi chặn bằng `withContext(Dispatchers.IO)` (hoặc dispatcher riêng qua `limitedParallelism`); nhiều giá trị thì dùng `Flow`/`callbackFlow`. Tầng domain gần như chỉ gồm hàm suspend gọi hàm suspend; chạy song song bằng `coroutineScope` + `async`/`awaitAll`, độc lập bằng `supervisorScope`, giới hạn thời gian bằng `withTimeoutOrNull`. Tầng trình bày là nơi BẮT ĐẦU coroutine: framework làm sẵn (`CoroutineWorker`, `viewModelScope`) hoặc scope tự tạo với `SupervisorJob`. Chọn scope là chọn KHI NÀO coroutine bị hủy.\n'
      'Hàm thường launch trên scope ngoài thì trả về ngay, lỗi và hủy thuộc về scope đó; hàm suspend thì chờ các con, và hủy người gọi thì hủy luôn các con. Có lựa chọn thì ưu tiên hàm suspend.\n'
      'Best practices tóm lại các chương trước: không `async { }.await()` ngay; `awaitAll`; hàm suspend phải gọi an toàn từ mọi luồng; `yield` trong việc nặng; Job không được kế thừa mà làm CHA, nên đừng truyền `Job()`/`SupervisorJob()` vào builder hay `withContext`; tạo scope với `SupervisorJob`; không `GlobalScope`; hàm trả về Flow không nên là suspend; một giá trị thì dùng hàm suspend.',
      'Apps usually have three layers. The data layer talks to libraries: use Retrofit/Room suspending functions; wrap callbacks with `suspendCancellableCoroutine`; wrap blocking calls with `withContext(Dispatchers.IO)` (or a dedicated dispatcher via `limitedParallelism`); for many values use `Flow`/`callbackFlow`. The domain layer is almost entirely suspending functions calling suspending functions; run things concurrently with `coroutineScope` + `async`/`awaitAll`, independently with `supervisorScope`, and bound time with `withTimeoutOrNull`. The presentation layer is where coroutines START: frameworks do it for you (`CoroutineWorker`, `viewModelScope`) or you build a scope with `SupervisorJob`. Choosing a scope means choosing WHEN the coroutine is cancelled.\n'
      'A regular function launching on an outer scope returns at once, and errors and cancellation belong to that scope; a suspending function waits for its children, and cancelling the caller cancels them. Given the choice, prefer the suspending function.\n'
      'Best practices sum up the earlier chapters: no immediate `async { }.await()`; `awaitAll`; suspending functions must be safe to call from any thread; `yield` in heavy work; Job is not inherited but used as a PARENT, so do not pass `Job()`/`SupervisorJob()` to builders or `withContext`; build scopes with `SupervisorJob`; no `GlobalScope`; functions returning Flow should not suspend; for a single value use a suspending function.')
    a(C + '.goal.g1', 'Đã thấy người gọi chờ các con với hàm suspend', 'Saw the caller wait for its children with a suspending function')
    a(C + '.goal.g2', 'Đã thử một sự cố tới cuối', 'Ran an incident to the end')
    a(C + '.sim.coroutines.launchsusp', 'launch hay suspend', 'launch or suspend')

    S = 'recap'
    a(C + '.sec.%s.title' % S, 'Ôn nhanh', 'Quick review')
    B(C, S, 1, 'ask', '`withContext(SupervisorJob()) { launch { … } }` có làm các con độc lập với nhau như `supervisorScope` không?', 'Does `withContext(SupervisorJob()) { launch { … } }` make the children independent like `supervisorScope` does?')
    B(C, S, 1, 'ans', 'Không. Job không được kế thừa: Job truyền vào trở thành CHA của coroutine mới, còn coroutine của `withContext` vẫn có Job thường, nên lỗi một con vẫn hủy các con khác. Tệ hơn, `withContext` giờ không còn là con của người gọi: hủy người gọi không hủy nó (phá structured concurrency). Chương cuối này gom những quy tắc như vậy thành best practices, cùng các mẫu dùng hằng ngày.', 'No. Job is not inherited: the Job you pass becomes the PARENT of the new coroutine, while `withContext`\'s own coroutine still has a regular Job, so one child\'s error still cancels the others. Worse, `withContext` is no longer a child of the caller: cancelling the caller does not cancel it (structured concurrency is broken). This final chapter gathers rules like this into best practices, along with everyday patterns.')

    S = 'data'
    a(C + '.sec.%s.title' % S, 'Tầng dữ liệu: thư viện, callback, hàm chặn', 'The data layer: libraries, callbacks, blocking functions')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Ba tầng: dữ liệu/adapter (repository, data source, nói chuyện với hệ thống khác), domain (logic nghiệp vụ: use case, service), và trình bày/API/UI (nơi khởi động tiến trình và xử lý kết quả). Ở tầng dữ liệu, nhiều thư viện đã hỗ trợ coroutine: Retrofit chỉ cần thêm `suspend` vào hàm khai báo request; Room hỗ trợ cả `suspend` (một thao tác) lẫn `Flow` (theo dõi bảng).', 'Three layers: data/adapters (repositories, data sources, talking to other systems), domain (business logic: use cases, services), and presentation/API/UI (where processes start and results are handled). In the data layer, many libraries already support coroutines: Retrofit only needs `suspend` on the request declaration; Room supports both `suspend` (one operation) and `Flow` (observing a table).')
    B(C, S, 2, 'p', 'Thư viện chỉ có callback thì đổi thành hàm suspend bằng `suspendCancellableCoroutine`: callback gọi `cont.resume(…)`; nếu yêu cầu hủy được thì hủy nó trong `invokeOnCancellation` ([[src:kx-suspendcancellable]]). Với callback thành công/thất bại riêng có ba kiểu trả về: `Result<News>` (resume `Result.success`/`Result.failure`), `News?` (resume null khi lỗi), hoặc resume giá trị và `resumeWithException(e)` khi lỗi (exception ném ra tại điểm suspend).', 'A callback-only library is turned into a suspending function with `suspendCancellableCoroutine`: the callback calls `cont.resume(…)`; if the request can be cancelled, cancel it in `invokeOnCancellation` ([[src:kx-suspendcancellable]]). For separate success/failure callbacks there are three return styles: `Result<News>` (resume `Result.success`/`Result.failure`), `News?` (resume null on error), or resume the value and `resumeWithException(e)` on error (the exception is thrown at the suspension point).')
    B(C, S, 3, 'kt', 'suspend fun requestNews(): News = suspendCancellableCoroutine { cont ->\n    val call = requestNewsApi(\n        onSuccess = { news -> cont.resume(news) },\n        onError = { e -> cont.resumeWithException(e) },\n    )\n    cont.invokeOnCancellation { call.cancel() }     // hủy request khi coroutine bị hủy\n}\n\nclass DiscSaveRepository(\n    private val discReader: DiscReader,\n    private val dispatcher: CoroutineContext = Dispatchers.IO,   // inject để test\n) : SaveRepository {\n    override suspend fun loadSave(name: String): SaveData =\n        withContext(dispatcher) { discReader.read("save/$name") }   // lời gọi CHẶN\n}\n\nclass CertificateGenerator {\n    private val dispatcher = Dispatchers.IO.limitedParallelism(5)   // giới hạn riêng, độc lập với IO\n    suspend fun generate(data: CertificateData) = withContext(dispatcher) {\n        Runtime.getRuntime().exec("generateCertificate " + data.toArgs())\n    }\n}', 'suspend fun requestNews(): News = suspendCancellableCoroutine { cont ->\n    val call = requestNewsApi(\n        onSuccess = { news -> cont.resume(news) },\n        onError = { e -> cont.resumeWithException(e) },\n    )\n    cont.invokeOnCancellation { call.cancel() }     // cancel the request when the coroutine is cancelled\n}\n\nclass DiscSaveRepository(\n    private val discReader: DiscReader,\n    private val dispatcher: CoroutineContext = Dispatchers.IO,   // injected for tests\n) : SaveRepository {\n    override suspend fun loadSave(name: String): SaveData =\n        withContext(dispatcher) { discReader.read("save/$name") }   // a BLOCKING call\n}\n\nclass CertificateGenerator {\n    private val dispatcher = Dispatchers.IO.limitedParallelism(5)   // its own limit, independent of IO\n    suspend fun generate(data: CertificateData) = withContext(dispatcher) {\n        Runtime.getRuntime().exec("generateCertificate " + data.toArgs())\n    }\n}')
    B(C, S, 4, 'p', 'Không bao giờ gọi hàm chặn trong hàm suspend thường: chặn luồng Main thì cả app đứng; chặn Default thì phí CPU. Luôn đặt dispatcher bằng `withContext` trước. `Dispatchers.IO` giới hạn 64 luồng (hoặc số nhân nếu lớn hơn) ([[src:kx-dispatchers]]); nếu một hàm có thể bị gọi bởi rất nhiều coroutine cùng lúc, hoặc bạn viết thư viện, hãy dùng dispatcher có giới hạn RIÊNG: `Dispatchers.IO.limitedParallelism(n)` ([[src:kx-limitedparallelism]]). Giới hạn nhỏ thì coroutine chờ nhau; lớn thì tốn bộ nhớ và CPU cho các luồng. Việc nặng CPU chạy trên `Dispatchers.Default`, việc sửa view trên `Dispatchers.Main.immediate`.', 'Never call a blocking function from an ordinary suspending function: blocking Main freezes the whole app; blocking Default wastes CPU. Always set the dispatcher with `withContext` first. `Dispatchers.IO` is limited to 64 threads (or the number of cores if larger) ([[src:kx-dispatchers]]); if a function may be called by very many coroutines at once, or you are writing a library, use a dispatcher with its OWN limit: `Dispatchers.IO.limitedParallelism(n)` ([[src:kx-limitedparallelism]]). A small limit makes coroutines wait for each other; a big one costs memory and CPU for threads. CPU-heavy work runs on `Dispatchers.Default`, view updates on `Dispatchers.Main.immediate`.')
    B(C, S, 5, 'p', 'Một giá trị → hàm suspend; nhiều giá trị theo thời gian → `Flow`. Gọi API một lần là hàm suspend; WebSocket hay listener là Flow, dựng bằng `callbackFlow` (nhớ `awaitClose`, xem chương FB). Cần dispatcher riêng cho builder thì dùng `flowOn` ở cuối: `flow { …fibonacci… }.flowOn(Dispatchers.Default)`, `channelFlow { …đọc file… }.flowOn(Dispatchers.IO)`.', 'One value → a suspending function; many values over time → a `Flow`. A one-off API call is a suspending function; a WebSocket or a listener is a Flow, built with `callbackFlow` (remember `awaitClose`, see chapter FB). If the builder needs a specific dispatcher, add `flowOn` at the end: `flow { …fibonacci… }.flowOn(Dispatchers.Default)`, `channelFlow { …read files… }.flowOn(Dispatchers.IO)`.')

    S = 'domain'
    a(C + '.sec.%s.title' % S, 'Tầng domain: gọi song song, độc lập, giới hạn thời gian', 'The domain layer: concurrent, independent, time-limited calls')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Ở tầng domain, gần như mọi thứ là hàm suspend gọi hàm suspend; KHÔNG giữ scope object ở đây, việc khởi động coroutine là của tầng trên. Muốn hai việc chạy song song, bọc thân hàm bằng `coroutineScope` và dùng `async`. Thay đổi đó chỉ được làm các việc chạy SONG SONG; mọi cơ chế khác (hủy, lỗi, context) giữ nguyên như bản tuần tự. Nhiều phần tử thì `map { async { … } }.awaitAll()`; muốn giới hạn số request đồng thời thì dùng `Semaphore` hay `flatMapMerge(concurrency = n)` (chương "Xử lý flow: map, filter, scan, merge/zip/combine, flatMap, retry, distinct").', 'In the domain layer nearly everything is a suspending function calling suspending functions; do NOT keep scope objects here, starting coroutines is the job of the layer above. To run two things in parallel, wrap the body in `coroutineScope` and use `async`. That change should only make things run IN PARALLEL; every other mechanism (cancellation, errors, context) stays as in the sequential version. For many elements use `map { async { … } }.awaitAll()`; to limit concurrent requests use a `Semaphore` or `flatMapMerge(concurrency = n)` (the chapter "Flow processing: map, filter, scan, merge/zip/combine, flatMap, retry, distinct").')
    B(C, S, 2, 'kt', 'suspend fun produceCurrentUser(): User = coroutineScope {\n    val profile = async { repo.getProfile() }\n    val friends = async { repo.getFriends() }\n    User(profile.await(), friends.await())\n}\n\nsuspend fun getOffers(categories: List<Category>): List<Offer> = coroutineScope {\n    categories.map { async { api.requestOffers(it) } }.awaitAll().flatten()\n}\n\nsuspend fun notifyAnalytics(actions: List<UserAction>) = supervisorScope {\n    actions.forEach { action -> launch { notifyAnalytics(action) } }   // độc lập: một cái lỗi không hủy cái khác\n}\n\nsuspend fun getUserOrNull(): User? = withTimeoutOrNull(5000) { fetchUser() }', 'suspend fun produceCurrentUser(): User = coroutineScope {\n    val profile = async { repo.getProfile() }\n    val friends = async { repo.getFriends() }\n    User(profile.await(), friends.await())\n}\n\nsuspend fun getOffers(categories: List<Category>): List<Offer> = coroutineScope {\n    categories.map { async { api.requestOffers(it) } }.awaitAll().flatten()\n}\n\nsuspend fun notifyAnalytics(actions: List<UserAction>) = supervisorScope {\n    actions.forEach { action -> launch { notifyAnalytics(action) } }   // independent: one failure does not cancel the others\n}\n\nsuspend fun getUserOrNull(): User? = withTimeoutOrNull(5000) { fetchUser() }')
    B(C, S, 3, 'p', 'Với Flow ở tầng domain, phần lớn chỉ là `map`, `filter`, `onEach`, thỉnh thoảng `scan` hay `flatMapMerge`; gộp nguồn bằng `merge`/`zip`/`combine`; nhiều nơi cùng theo dõi một flow thì `shareIn(scope, WhileSubscribed())` (chương "Xử lý flow: map, filter, scan, merge/zip/combine, flatMap, retry, distinct" và chương A7).', 'For Flow in the domain layer it is mostly `map`, `filter`, `onEach`, occasionally `scan` or `flatMapMerge`; combine sources with `merge`/`zip`/`combine`; when several places observe one flow, `shareIn(scope, WhileSubscribed())` (the chapter "Flow processing: map, filter, scan, merge/zip/combine, flatMap, retry, distinct" and chapter A7).')

    S = 'present'
    a(C + '.sec.%s.title' % S, 'Tầng trình bày: nơi coroutine bắt đầu', 'The presentation layer: where coroutines start')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Nhiều framework khởi động coroutine giúp ta: trên Android, `CoroutineWorker.doWork()` của WorkManager là hàm suspend, thư viện chạy nó trong coroutine và hủy khi công việc bị hủy ([[src:and-coroutineworker]]). Phần còn lại thường dùng `viewModelScope`/`lifecycleScope` ([[src:and-co-lifecycle]]). Khi không có gì sẵn, tự tạo scope bằng hàm `CoroutineScope(…)`, gần như luôn có `SupervisorJob` (một lỗi không hủy mọi coroutine khác), có thể thêm dispatcher và `CoroutineExceptionHandler`. Câu hỏi "dùng scope nào?" thường rút về "khi nào việc này nên bị hủy?".', 'Many frameworks start coroutines for us: on Android, WorkManager\'s `CoroutineWorker.doWork()` is a suspending function the library runs in a coroutine and cancels when the work is cancelled ([[src:and-coroutineworker]]). Otherwise we usually use `viewModelScope`/`lifecycleScope` ([[src:and-co-lifecycle]]). When nothing fits, build a scope with the `CoroutineScope(…)` function, almost always with a `SupervisorJob` (one failure does not cancel every other coroutine), optionally with a dispatcher and a `CoroutineExceptionHandler`. The question "which scope?" usually reduces to "when should this work be cancelled?".')
    B(C, S, 2, 'kt', 'class CoroutineDownloadWorker(context: Context, params: WorkerParameters) : CoroutineWorker(context, params) {\n    override suspend fun doWork(): Result {\n        val data = downloadSynchronously()\n        saveData(data)\n        return Result.success()\n    }\n}\n\nval analyticsScope = CoroutineScope(SupervisorJob())\n\nabstract class BaseViewModel : ViewModel() {\n    private val _failure = MutableStateFlow<Throwable?>(null)\n    val failure: StateFlow<Throwable?> = _failure\n    private val handler = CoroutineExceptionHandler { _, t -> _failure.value = t }\n    private val context = Dispatchers.Main + SupervisorJob() + handler\n    protected val scope = CoroutineScope(context)\n    override fun onCleared() { context.cancelChildren() }\n}', 'class CoroutineDownloadWorker(context: Context, params: WorkerParameters) : CoroutineWorker(context, params) {\n    override suspend fun doWork(): Result {\n        val data = downloadSynchronously()\n        saveData(data)\n        return Result.success()\n    }\n}\n\nval analyticsScope = CoroutineScope(SupervisorJob())\n\nabstract class BaseViewModel : ViewModel() {\n    private val _failure = MutableStateFlow<Throwable?>(null)\n    val failure: StateFlow<Throwable?> = _failure\n    private val handler = CoroutineExceptionHandler { _, t -> _failure.value = t }\n    private val context = Dispatchers.Main + SupervisorJob() + handler\n    protected val scope = CoroutineScope(context)\n    override fun onCleared() { context.cancelChildren() }\n}')
    B(C, S, 3, 'p', '`runBlocking` chặn luồng hiện tại tới khi coroutine xong, nên chỉ dùng khi THẬT SỰ muốn chặn: bọc `main` hoặc hàm test. Cả hai đã có thay thế hiện đại: `suspend fun main() = coroutineScope { … }` và `runTest`. Khi collect Flow ở tầng này, mẫu quen thuộc là `onStart`/`onCompletion`/`onEach`/`catch` (đặt `catch` CUỐI để bắt mọi lỗi) rồi `launchIn(viewModelScope)`; trạng thái để trong `StateFlow`, sự kiện cho nhiều người nghe để trong `SharedFlow`. Marcin Moskała dùng một hàm tự viết `launchOnStarted { }` trong Activity; trong thư viện AndroidX, cách tương ứng là `repeatOnLifecycle(Lifecycle.State.STARTED) { … }` ([[src:and-co-lifecycle]]).', '`runBlocking` blocks the current thread until the coroutine finishes, so use it only when you REALLY want to block: wrapping `main` or a test function. Both have modern alternatives: `suspend fun main() = coroutineScope { … }` and `runTest`. When collecting Flow in this layer, the familiar pattern is `onStart`/`onCompletion`/`onEach`/`catch` (put `catch` LAST to catch everything) then `launchIn(viewModelScope)`; keep state in a `StateFlow`, and events for several listeners in a `SharedFlow`. Marcin Moskała uses a home-made `launchOnStarted { }` in the Activity; the AndroidX equivalent is `repeatOnLifecycle(Lifecycle.State.STARTED) { … }` ([[src:and-co-lifecycle]]).')

    S = 'launchsusp'
    a(C + '.sec.%s.title' % S, 'Hàm thường launch trên scope, hay hàm suspend?', 'A regular function launching on a scope, or a suspending function?')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Cần làm nhiều việc đồng thời, có hai kiểu hàm: hàm THƯỜNG dùng một scope object (`notificationScope.launch`), hoặc hàm SUSPEND (`supervisorScope { launch … }`). Chỉ nhìn chữ ký đã biết khác biệt. Hàm thường nhận scope: chỉ khởi động coroutine, không chờ (chạy vài mili giây); lỗi do scope xử lý (Marcin Moskała viết cho backend: "thường in ra rồi bỏ qua"; trên Android, scope không có `CoroutineExceptionHandler` thì lỗi làm crash app); context và quan hệ cha con lấy từ scope, muốn hủy phải hủy scope. Hàm suspend: không xong trước khi mọi coroutine của nó xong (một cơ chế đồng bộ quan trọng); không hủy cha mà ném hoặc nuốt lỗi như hàm thường; context và quan hệ cha con lấy từ coroutine gọi nó.', 'To do several things concurrently there are two kinds of function: a REGULAR function using a scope object (`notificationScope.launch`), or a SUSPENDING function (`supervisorScope { launch … }`). The signature alone tells you the difference. The regular function with a scope: only starts coroutines and does not wait (runs in milliseconds); errors are handled by the scope (Marcin Moskała, writing with the backend in mind, says "usually printed and ignored"; on Android, a scope without a `CoroutineExceptionHandler` lets the error crash the app); context and parent link come from the scope, and to cancel you cancel the scope. The suspending function: does not finish before all its coroutines finish (an important synchronization mechanism); does not cancel its parent but throws or swallows errors like a normal function; context and parent link come from the coroutine that called it.')
    B(C, S, 2, 'predict', 'Với kiểu hàm suspend và sự cố "người gọi bị hủy ở 1200 ms", lần gửi n1 (1000 ms), n2 (2000 ms), n3 (1500 ms) mỗi cái kết thúc thế nào? Với kiểu hàm thường thì sao?', 'With the suspending function and the incident "the caller is cancelled at 1200 ms", how does each send end: n1 (1000 ms), n2 (2000 ms), n3 (1500 ms)? And with the regular function?')
    B(C, S, 2, 'ans', 'Hàm suspend: n1 xong lúc 1000; lúc 1200 người gọi bị hủy nên n2 và n3 (con của nó) bị hủy. Hàm thường: người gọi đã đi tiếp từ 0 ms, và các lần gửi thuộc `notificationScope` nên vẫn xong cả ba (1000, 1500, 2000) dù người gọi bị hủy. Chạy cả hai trong mô phỏng ngay dưới.', 'Suspending function: n1 finishes at 1000; at 1200 the caller is cancelled, so n2 and n3 (its children) are cancelled. Regular function: the caller already moved on at 0 ms, and the sends belong to `notificationScope`, so all three still finish (1000, 1500, 2000) although the caller was cancelled. Run both in the simulation just below.')
    B(C, S, 3, 'p', 'Có lựa chọn thì ưu tiên hàm suspend vì dễ điều khiển và đồng bộ hơn; nhưng coroutine phải bắt đầu ở đâu đó, và chỗ đó là hàm thường với scope. Đôi khi cần lai: hàm suspend làm phần việc chính, rồi khởi động một việc ĐỘC LẬP trên scope ngoài, ví dụ gửi sự kiện analytics sau khi đồng bộ user: `eventsScope.launch { sendEvent(UserSynchronized) }`. Khi đó hàm không chờ việc gửi, việc gửi không bị hủy cùng người gọi, và `eventsScope` quyết định context (scope không còn active thì không gửi). Dùng có cân nhắc. Ngược lại, kết thúc `coroutineScope { … }` bằng một `launch` trên chính nó là vô nghĩa: hàm vẫn chờ nó.', 'Given the choice, prefer the suspending function: easier to control and synchronize; but coroutines must start somewhere, and that place is a regular function with a scope. Sometimes you need a hybrid: a suspending function does the essential work, then starts an INDEPENDENT process on an outer scope, e.g. sending an analytics event after syncing the user: `eventsScope.launch { sendEvent(UserSynchronized) }`. Then the function does not wait for the send, the send is not cancelled with the caller, and `eventsScope` decides the context (if the scope is no longer active, nothing is sent). Use it deliberately. Conversely, ending a `coroutineScope { … }` with a `launch` on itself is pointless: the function still waits for it.')

    S = 'recipes'
    a(C + '.sec.%s.title' % S, 'Công thức: mapAsync, suspendLazy, ConnectionPool, raceOf, retry', 'Recipes: mapAsync, suspendLazy, ConnectionPool, raceOf, retry')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Tác giả gom vài hàm hay dùng ([[src:kt-recipes]]). `mapAsync` gói `coroutineScope` + `map { async }` + `awaitAll`, có tham số giới hạn đồng thời bằng `Semaphore`. `suspendLazy` thay cho `by lazy` (không gọi được hàm suspend trong `lazy` vì lambda của nó không inline): trả về một hàm `suspend () -> T`, dùng `Mutex` (không thay bằng dispatcher một luồng được, vì không muốn hai tiến trình cùng tính dù tiến trình trước đang suspend) và bỏ tham chiếu `initializer` sau khi dùng để tránh rò bộ nhớ.', 'The author collects some handy functions ([[src:kt-recipes]]). `mapAsync` wraps `coroutineScope` + `map { async }` + `awaitAll`, with a concurrency limit via a `Semaphore`. `suspendLazy` replaces `by lazy` (you cannot call a suspending function in `lazy` because its lambda is not inline): it returns a `suspend () -> T` function, uses a `Mutex` (a single-thread dispatcher would not do, because we do not want two processes computing even while the first is suspended), and drops the `initializer` reference after use to avoid a memory leak.')
    B(C, S, 2, 'kt', 'suspend fun <T, R> List<T>.mapAsync(\n    concurrencyLimit: Int = Int.MAX_VALUE,\n    transformation: suspend (T) -> R,\n): List<R> = coroutineScope {\n    val semaphore = Semaphore(concurrencyLimit)\n    this@mapAsync.map { async { semaphore.withPermit { transformation(it) } } }.awaitAll()\n}\n\nfun <T> suspendLazy(initializer: suspend () -> T): suspend () -> T {\n    var initializer: (suspend () -> T)? = initializer\n    val mutex = Mutex()\n    var holder: Any? = Any()\n    return {\n        if (initializer == null) holder as T\n        else mutex.withLock {\n            initializer?.let { holder = it(); initializer = null }\n            holder as T\n        }\n    }\n}\nval getConnection = suspendLazy { makeConnection() }   // gọi 3 lần: chỉ tạo kết nối một lần\n\nsuspend fun <T> raceOf(racer: suspend CoroutineScope.() -> T, vararg racers: suspend CoroutineScope.() -> T): T =\n    coroutineScope {\n        select {\n            (listOf(racer) + racers).forEach { r ->\n                async { r() }.onAwait { coroutineContext.job.cancelChildren(); it }\n            }\n        }\n    }\nsuspend fun fetchUserData(): UserData = raceOf({ service1.fetchUserData() }, { service2.fetchUserData() })', 'suspend fun <T, R> List<T>.mapAsync(\n    concurrencyLimit: Int = Int.MAX_VALUE,\n    transformation: suspend (T) -> R,\n): List<R> = coroutineScope {\n    val semaphore = Semaphore(concurrencyLimit)\n    this@mapAsync.map { async { semaphore.withPermit { transformation(it) } } }.awaitAll()\n}\n\nfun <T> suspendLazy(initializer: suspend () -> T): suspend () -> T {\n    var initializer: (suspend () -> T)? = initializer\n    val mutex = Mutex()\n    var holder: Any? = Any()\n    return {\n        if (initializer == null) holder as T\n        else mutex.withLock {\n            initializer?.let { holder = it(); initializer = null }\n            holder as T\n        }\n    }\n}\nval getConnection = suspendLazy { makeConnection() }   // called 3 times: the connection is made once\n\nsuspend fun <T> raceOf(racer: suspend CoroutineScope.() -> T, vararg racers: suspend CoroutineScope.() -> T): T =\n    coroutineScope {\n        select {\n            (listOf(racer) + racers).forEach { r ->\n                async { r() }.onAwait { coroutineContext.job.cancelChildren(); it }\n            }\n        }\n    }\nsuspend fun fetchUserData(): UserData = raceOf({ service1.fetchUserData() }, { service2.fetchUserData() })')
    B(C, S, 3, 'p', '`ConnectionPool<K, V>` mở rộng ý tưởng `shareIn` cho kết nối CÓ THAM SỐ (ví dụ theo dõi từng luồng chat): lần đầu `getConnection(key)` tạo `builder(key).shareIn(scope, WhileSubscribed())` và lưu trong map; các lần sau dùng lại. `getConnection` là hàm thường (như mọi hàm trả về Flow) nên dùng `synchronized` để bảo vệ map; nó chạy rất nhanh vì chỉ định nghĩa flow, kết nối chỉ mở khi có người collect. `raceOf` chạy nhiều tiến trình, lấy kết quả của cái xong TRƯỚC và hủy phần còn lại (dùng `select`, chương CH).', '`ConnectionPool<K, V>` extends the `shareIn` idea to PARAMETERIZED connections (e.g. observing each chat thread): the first `getConnection(key)` creates `builder(key).shareIn(scope, WhileSubscribed())` and stores it in a map; later calls reuse it. `getConnection` is a regular function (like every function returning Flow), so it uses `synchronized` to protect the map; it is very fast because it only defines a flow, and a connection opens only when someone collects. `raceOf` runs several processes, takes the result of whichever finishes FIRST and cancels the rest (using `select`, chapter CH).')
    B(C, S, 4, 'p', 'Thử lại hàm suspend: không có `retry` có sẵn như với Flow. Một hàm `retryWhen(predicate, operation)` tốt cần hai điều: KHÔNG BAO GIỜ thử lại `CancellationException` (để không phá cơ chế hủy), và gắn các lỗi trước vào lỗi cuối bằng `addSuppressed` để thấy cả lịch sử. Thuật toán phổ biến là exponential backoff: mỗi lần thất bại chờ lâu hơn (có thể thêm "jitter" ngẫu nhiên), tới một mức trần.', 'Retrying a suspending function: there is no built-in `retry` as for Flow. A good `retryWhen(predicate, operation)` needs two things: NEVER retry a `CancellationException` (so as not to break cancellation), and attach earlier errors to the final one with `addSuppressed` to keep the whole history. A popular algorithm is exponential backoff: wait longer after each failure (optionally with random "jitter"), up to a cap.')
    B(C, S, 5, 'kt', 'inline fun <T> retryWhen(predicate: (Throwable, retries: Int) -> Boolean, operation: () -> T): T {\n    var retries = 0\n    var fromDownstream: Throwable? = null\n    while (true) {\n        try {\n            return operation()\n        } catch (e: Throwable) {\n            if (fromDownstream != null) e.addSuppressed(fromDownstream)\n            fromDownstream = e\n            if (e is CancellationException || !predicate(e, retries++)) throw e\n        }\n    }\n}\n\nsuspend fun requestWithRetry() = retryWhen(\n    predicate = { e, retries ->\n        val backoff = 100L * 2.0.pow(retries).toLong()\n        delay(minOf(10_000L, backoff))          // trần 10 s (lỗi hay gặp là maxOf: luôn chờ ít nhất 10 s)\n        retries < 10 && e is IllegalStateException\n    },\n) { requestData() }', 'inline fun <T> retryWhen(predicate: (Throwable, retries: Int) -> Boolean, operation: () -> T): T {\n    var retries = 0\n    var fromDownstream: Throwable? = null\n    while (true) {\n        try {\n            return operation()\n        } catch (e: Throwable) {\n            if (fromDownstream != null) e.addSuppressed(fromDownstream)\n            fromDownstream = e\n            if (e is CancellationException || !predicate(e, retries++)) throw e\n        }\n    }\n}\n\nsuspend fun requestWithRetry() = retryWhen(\n    predicate = { e, retries ->\n        val backoff = 100L * 2.0.pow(retries).toLong()\n        delay(minOf(10_000L, backoff))          // 10 s cap (a common slip is maxOf: it always waits at least 10 s)\n        retries < 10 && e is IllegalStateException\n    },\n) { requestData() }')
    B(C, S, 6, 'note', 'Ba chỗ dễ sai trong công thức này, đã sửa trong mã trên. (1) Backoff dùng `maxOf(10_000L, 100L * times)`: nghĩa là luôn chờ ÍT NHẤT 10 giây; ý định là đặt trần, phải là `minOf`. (2) Các ví dụ `retryWhen`/`retry` cho HÀM SUSPEND dùng biến `attempt` không tồn tại (biến đúng là `retries`); ở ví dụ cho Flow thì `attempt` là tham số lambda hợp lệ. (3) Hàm `retry` đơn giản đầu tiên bắt `Throwable` và lặp mãi: nó bắt luôn `CancellationException`, nên coroutine bị hủy sẽ quay vòng thay vì dừng (xem phần bug). Ngoài ra output của ví dụ `suspendLazy` in hai dòng "(1 sec)", nhưng thực tế chỉ có một lần chờ 1 giây.', 'Three easy mistakes in this recipe, fixed in the code above. (1) The backoff uses `maxOf(10_000L, 100L * times)`: that means always waiting AT LEAST 10 seconds; the intent is a cap, so it must be `minOf`. (2) The `retryWhen`/`retry` examples for SUSPENDING FUNCTIONS use a variable `attempt` that does not exist (the right one is `retries`); in the Flow example, `attempt` is a valid lambda parameter. (3) The first, simple `retry` catches `Throwable` and loops forever: it also catches `CancellationException`, so a cancelled coroutine spins instead of stopping (see the bugs section). Also, the output of the `suspendLazy` example prints two "(1 sec)" lines, but there is really only one 1-second wait.')
    B(C, S, 6, 'kind', 'source')

    S = 'java'
    a(C + '.sec.%s.title' % S, 'Dùng hàm suspend từ Java', 'Using suspending functions from Java')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Java không có hàm suspend: với Java, `suspend fun checkConnection(): Boolean` là một hàm nhận thêm tham số `Continuation` (chương U4). Cách dễ nhất cho người dùng Java là cung cấp biến thể CHẶN bằng `runBlocking` (lớp bọc riêng, hoặc hàm `…Blocking()` cạnh hàm suspend). Trên JVM có thể trả `CompletableFuture` bằng builder `future { }` trên một scope ([[src:kx-future]]). Nếu buộc phải gọi hàm suspend từ Java (ví dụ test viết bằng Groovy/Spock), có thể gọi `BuildersKt.runBlocking(EmptyCoroutineContext.INSTANCE, (s, c) -> connector.checkConnection(c))`, và bọc trong một tiện ích để khỏi xử lý `InterruptedException` mỗi lần.', 'Java has no suspending functions: to Java, `suspend fun checkConnection(): Boolean` is a function with an extra `Continuation` parameter (chapter U4). The easiest option for Java users is a BLOCKING variant via `runBlocking` (a separate wrapper class, or a `…Blocking()` function next to the suspending one). On the JVM you can return a `CompletableFuture` with the `future { }` builder on a scope ([[src:kx-future]]). If you must call a suspending function from Java (e.g. tests written in Groovy/Spock), call `BuildersKt.runBlocking(EmptyCoroutineContext.INSTANCE, (s, c) -> connector.checkConnection(c))`, and wrap it in a utility so you do not handle `InterruptedException` every time.')
    B(C, S, 2, 'kt', 'class AnkiConnector {\n    suspend fun checkConnection(): Boolean = TODO()\n    fun checkConnectionBlocking(): Boolean = runBlocking { checkConnection() }     // cho Java\n}\n\nclass AnkiConnectorFuture {\n    private val connector = AnkiConnector()\n    private val scope = CoroutineScope(SupervisorJob())\n    fun checkConnection(): CompletableFuture<Boolean> = scope.future { connector.checkConnection() }\n}', 'class AnkiConnector {\n    suspend fun checkConnection(): Boolean = TODO()\n    fun checkConnectionBlocking(): Boolean = runBlocking { checkConnection() }     // for Java\n}\n\nclass AnkiConnectorFuture {\n    private val connector = AnkiConnector()\n    private val scope = CoroutineScope(SupervisorJob())\n    fun checkConnection(): CompletableFuture<Boolean> = scope.future { connector.checkConnection() }\n}')

    S = 'best'
    a(C + '.sec.%s.title' % S, 'Best practices (kèm lý do)', 'Best practices (with the reasons)')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', '(1) Không `async { … }.await()` ngay: không có gì chạy trong lúc chờ thì `async` vô nghĩa; cần scope thì `coroutineScope`, cần đổi context thì `withContext`. Khi chạy vài việc song song, dùng `async` cho mọi việc (kể cả việc cuối) cho dễ đọc. (2) Dùng `coroutineScope` thay `withContext(EmptyCoroutineContext)`. (3) Dùng `awaitAll` thay `map { it.await() }`: `awaitAll` dừng chờ ngay khi một tác vụ lỗi ([[src:kx-awaitall]]), còn `map { await }` chờ lần lượt tới tác vụ lỗi. (4) Hàm suspend phải gọi an toàn từ mọi luồng: việc chặn đặt `withContext(Dispatchers.IO)` (hoặc dispatcher riêng), việc nặng CPU đặt `Dispatchers.Default`, NGAY TRONG hàm; hàm trả về Flow dùng `flowOn` ở cuối; inject dispatcher để test. (5) Ưu tiên `Dispatchers.Main.immediate` (tránh dispatch lại khi không cần). (6) Gọi `yield()` giữa các khối nặng CPU: hỗ trợ hủy và nhường lượt; trong builder có thể dùng `ensureActive()`.', '(1) No immediate `async { … }.await()`: if nothing runs while waiting, `async` is pointless; if you need a scope use `coroutineScope`, to change context use `withContext`. When running several things in parallel, use `async` for all of them (even the last) for readability. (2) Use `coroutineScope` instead of `withContext(EmptyCoroutineContext)`. (3) Use `awaitAll` instead of `map { it.await() }`: `awaitAll` stops waiting as soon as one task fails ([[src:kx-awaitall]]), while `map { await }` waits one by one until it reaches the failing task. (4) Suspending functions must be safe to call from any thread: put blocking work in `withContext(Dispatchers.IO)` (or a dedicated dispatcher) and CPU-heavy work in `Dispatchers.Default`, INSIDE the function; functions returning Flow use `flowOn` at the end; inject the dispatcher for tests. (5) Prefer `Dispatchers.Main.immediate` (avoids redispatching when not needed). (6) Call `yield()` between CPU-heavy blocks: it supports cancellation and yields the thread; inside builders you can use `ensureActive()`.')
    B(C, S, 2, 'p', '(7) Hàm suspend chờ các con: `coroutineScope`/`withContext` không trả về trước khi mọi coroutine của nó xong. (8) Job KHÔNG được kế thừa mà làm CHA: `runBlocking(SupervisorJob())` hay `withContext(SupervisorJob())` không làm các con độc lập (dùng `supervisorScope`), và `withContext(Job())` còn tách hàm khỏi người gọi: hủy người gọi không hủy nó, việc tiếp tục chạy và rò tài nguyên. (9) Tạo scope bằng `CoroutineScope(SupervisorJob())`, không phải `Job()`. (10) Cân nhắc `scope.coroutineContext.cancelChildren()` thay `scope.cancel()`: scope bị hủy thì không dùng lại được. (11) Trước khi dùng một scope, nghĩ xem nó bị hủy khi nào. (12) Không dùng `GlobalScope`: không quan hệ, không hủy, khó thay khi test; ít nhất hãy tạo `CoroutineScope(SupervisorJob())`. (13) Tránh builder `Job()` trừ khi dựng scope: `Job()` không tự hoàn tất khi các con xong, nên `job.join()` chờ mãi; hãy giữ Job trả về từ `launch`. (14) Hàm trả về Flow không nên là `suspend`. (15) Chỉ một giá trị thì dùng hàm suspend, không dùng Flow (lời khuyên gây tranh luận nhất; theo quy ước của team nếu đã khác).', '(7) Suspending functions await their children: `coroutineScope`/`withContext` do not return before every coroutine they started is done. (8) Job is NOT inherited but used as a PARENT: `runBlocking(SupervisorJob())` or `withContext(SupervisorJob())` do not make children independent (use `supervisorScope`), and `withContext(Job())` even detaches the function from its caller: cancelling the caller does not cancel it, the work keeps running and leaks resources. (9) Build scopes with `CoroutineScope(SupervisorJob())`, not `Job()`. (10) Consider `scope.coroutineContext.cancelChildren()` instead of `scope.cancel()`: a cancelled scope cannot be reused. (11) Before using a scope, think about when it is cancelled. (12) Do not use `GlobalScope`: no relationship, no cancellation, hard to replace in tests; at least create `CoroutineScope(SupervisorJob())`. (13) Avoid the `Job()` builder except to build a scope: `Job()` does not complete when its children finish, so `job.join()` waits forever; keep the Job returned by `launch` instead. (14) Functions returning Flow should not be `suspend`. (15) For a single value use a suspending function, not a Flow (the most debated advice; follow your team\'s convention if it differs).')
    B(C, S, 3, 'kt', '// Đừng: một phần chạy khi GỌI hàm, phần còn lại khi COLLECT; collect muộn thì dùng danh sách cũ\nsuspend fun observeNewsServices(): Flow<News> {\n    val newsServices = fetchNewsServices()\n    return newsServices.asFlow().flatMapMerge { it.observe() }\n}\n// Nên: gói toàn bộ tiến trình vào flow\nfun observeNewsServices(): Flow<News> =\n    flow { emitAll(fetchNewsServices().asFlow()) }.flatMapMerge { it.observe() }\n\n// Đừng: Job() không tự hoàn tất\nval job = Job()\nlaunch(job) { delay(1000); println("Text 1") }\nlaunch(job) { delay(2000); println("Text 2") }\njob.join()                       // chờ mãi; "Will not be printed"', '// Don\'t: part runs when the function is CALLED, the rest on COLLECT; a late collect uses a stale list\nsuspend fun observeNewsServices(): Flow<News> {\n    val newsServices = fetchNewsServices()\n    return newsServices.asFlow().flatMapMerge { it.observe() }\n}\n// Do: pack the whole process into the flow\nfun observeNewsServices(): Flow<News> =\n    flow { emitAll(fetchNewsServices().asFlow()) }.flatMapMerge { it.observe() }\n\n// Don\'t: Job() does not complete by itself\nval job = Job()\nlaunch(job) { delay(1000); println("Text 1") }\nlaunch(job) { delay(2000); println("Text 2") }\njob.join()                       // waits forever; "Will not be printed"')
    B(C, S, 4, 'note', 'Câu tác giả muốn người đọc nhớ: best practices đôi khi phải bị vi phạm; chúng là hướng dẫn cho tình huống thường gặp, không phải luật cho mọi tình huống. Khi vi phạm, hãy biết rõ mình đổi lấy điều gì (dùng sim ở trên để kiểm).', 'The sentence the author wants you to remember: best practices sometimes have to be broken; they are guidelines for standard situations, not rules for every situation. When you break one, know exactly what you are trading (use the simulation above to check).')
    B(C, S, 4, 'kind', 'mechanism')

    S = 'bugs'
    a(C + '.sec.%s.title' % S, 'Bug thường gặp khi đưa coroutine vào dự án thật', 'Common bugs when putting coroutines into a real project')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'bug', 'Sau khi rời màn hình, log vẫn ghi "Retrying…" liên tục và CPU không xuống.', 'After leaving the screen, the log keeps printing "Retrying…" and the CPU does not settle.')
    B(C, S, 1, 'cause', 'Một hàm `retry { }` tự viết bắt `Throwable` (hoặc `Exception`) rồi lặp lại. Khi coroutine bị hủy, `delay` hay lời gọi suspend bên trong ném `CancellationException`, bị bắt luôn, và vòng lặp chạy tiếp: coroutine không bao giờ dừng.', 'A home-made `retry { }` catches `Throwable` (or `Exception`) and loops. When the coroutine is cancelled, `delay` or the suspending call inside throws `CancellationException`, which gets caught too, and the loop continues: the coroutine never stops.')
    B(C, S, 1, 'fix', 'Luôn ném lại `CancellationException` (`if (e is CancellationException) throw e`), hoặc dùng `retryWhen` như phần công thức; với Flow thì dùng `retry`/`retryWhen` có sẵn.', 'Always rethrow `CancellationException` (`if (e is CancellationException) throw e`), or use the `retryWhen` from the recipes section; for Flow use the built-in `retry`/`retryWhen`.')
    B(C, S, 2, 'bug', 'Bấm "Hủy tải" trên màn hình nhưng việc tải ảnh vẫn chạy tới hết.', 'Pressing "Cancel download" on the screen, but the image download still runs to the end.')
    B(C, S, 2, 'cause', 'Repository viết `suspend fun download() = withContext(Job() + Dispatchers.IO) { … }` (hoặc `SupervisorJob()`). Job truyền vào làm CHA mới, nên coroutine của `withContext` không còn là con của coroutine gọi; hủy người gọi không lan tới nó.', 'The repository has `suspend fun download() = withContext(Job() + Dispatchers.IO) { … }` (or `SupervisorJob()`). The passed Job becomes the new PARENT, so `withContext`\'s coroutine is no longer a child of the caller; cancelling the caller does not reach it.')
    B(C, S, 2, 'fix', 'Chỉ truyền dispatcher: `withContext(Dispatchers.IO) { … }`. Muốn các con độc lập thì dùng `supervisorScope`.', 'Pass only the dispatcher: `withContext(Dispatchers.IO) { … }`. If you want independent children, use `supervisorScope`.')
    B(C, S, 3, 'bug', 'Hàm `suspend fun observePrices(): Flow<Price>` được gọi trong `init` của ViewModel nhưng chỉ collect khi người dùng mở tab; giá hiển thị dựa trên danh sách sản phẩm cũ từ lúc mở app.', '`suspend fun observePrices(): Flow<Price>` is called in the ViewModel\'s `init` but only collected when the user opens a tab; the prices shown are based on the product list from app start.')
    B(C, S, 3, 'cause', 'Hàm suspend trả về Flow chạy một phần (tải danh sách sản phẩm) lúc GỌI, phần còn lại lúc COLLECT. Collect muộn thì dùng dữ liệu đã tải từ trước.', 'A suspending function returning a Flow runs part of the work (loading the product list) when CALLED, the rest when COLLECTED. A late collect uses data loaded long before.')
    B(C, S, 3, 'fix', 'Bỏ `suspend`, gói việc tải vào trong flow: `fun observePrices() = flow { emitAll(loadProducts().asFlow()) }.flatMapMerge { observePrice(it) }`.', 'Drop `suspend` and move the loading into the flow: `fun observePrices() = flow { emitAll(loadProducts().asFlow()) }.flatMapMerge { observePrice(it) }`.')

    S = 'exercises'
    a(C + '.sec.%s.title' % S, 'Bài tập', 'Exercises')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ex', 'Bọc API callback này thành hàm suspend có hủy: `fun loadAvatar(url: String, onLoaded: (Bitmap) -> Unit, onError: (Throwable) -> Unit): Cancellable`.', 'Wrap this callback API into a cancellable suspending function: `fun loadAvatar(url: String, onLoaded: (Bitmap) -> Unit, onError: (Throwable) -> Unit): Cancellable`.')
    B(C, S, 1, 'hint', '`suspendCancellableCoroutine`, `resume`, `resumeWithException`, `invokeOnCancellation`.', '`suspendCancellableCoroutine`, `resume`, `resumeWithException`, `invokeOnCancellation`.')
    B(C, S, 1, 'sol', 'Ném lỗi bằng `resumeWithException` để người gọi dùng `try/catch` như hàm thường; hủy request trong `invokeOnCancellation` để không tải khi người gọi không cần nữa.', 'Throw errors with `resumeWithException` so callers use `try/catch` as with a normal function; cancel the request in `invokeOnCancellation` so nothing is downloaded once the caller no longer needs it.')
    B(C, S, 1, 'solkt', 'suspend fun loadAvatar(url: String): Bitmap = suspendCancellableCoroutine { cont ->\n    val request = loadAvatar(\n        url,\n        onLoaded = { cont.resume(it) },\n        onError = { cont.resumeWithException(it) },\n    )\n    cont.invokeOnCancellation { request.cancel() }\n}')
    B(C, S, 2, 'ex', 'Sửa hàm sau theo best practices và nói rõ mỗi chỗ sửa:', 'Fix this function according to the best practices and explain each change:')
    B(C, S, 2, 'exkt', 'suspend fun loadDashboard(): Dashboard = withContext(SupervisorJob()) {\n    val user = async { userRepo.getUser() }.await()\n    val news = newsIds.map { async { newsRepo.get(it) } }.map { it.await() }\n    GlobalScope.launch { analytics.send("dashboard") }\n    Dashboard(user, news)\n}')
    B(C, S, 2, 'sol', 'Bỏ `withContext(SupervisorJob())` (tách hàm khỏi người gọi, không làm gì có ích): dùng `coroutineScope`. `async { }.await()` ngay thì gọi thẳng; nhưng muốn user và news chạy song song thì giữ `async` cho cả hai và `await` sau. `map { it.await() }` → `awaitAll()`. `GlobalScope` → một scope có ý nghĩa được inject (`analyticsScope`), việc độc lập có chủ đích.', 'Drop `withContext(SupervisorJob())` (it detaches the function from its caller and does nothing useful): use `coroutineScope`. An immediate `async { }.await()` should be a direct call; but to run user and news in parallel, keep `async` for both and `await` later. `map { it.await() }` → `awaitAll()`. `GlobalScope` → a meaningful injected scope (`analyticsScope`), a deliberate independent process.')
    B(C, S, 2, 'solkt', 'suspend fun loadDashboard(): Dashboard = coroutineScope {\n    val user = async { userRepo.getUser() }\n    val news = async { newsIds.map { async { newsRepo.get(it) } }.awaitAll() }\n    analyticsScope.launch { analytics.send("dashboard") }\n    Dashboard(user.await(), news.await())\n}')

    S = 'recall'
    a(C + '.sec.%s.title' % S, 'Tự trả lời', 'Answer it yourself')
